const request = require('request');

const options = {
  method: 'POST',
  url: 'http://localhost:8080/rest/v2.0/companies/1234/projects/1234/assets/asset_types/%7Basset_type_id%7D/attachment',
  headers: {
    'Procore-Company-Id': 'SOME_INTEGER_VALUE',
    'Accept-Language': 'SOME_STRING_VALUE',
    'content-type': 'application/json'
  },
  body: [
    {
      attachment_type_id: 'string',
      file_name: 'string',
      attachment_file_id: 'string',
      description: 'string',
      attachment_source: 'LOCAL_FILE_UPLOAD'
    }
