  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/projects/1234/assets/asset_types/%7Basset_type_id%7D/attachment"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
    Content = new StringContent("[{\"attachment_type_id\":\"string\",\"file_name\":\"string\",\"attachment_file_id\":\"string\",\"description\":\"string\",\"attachment_source\":\"LOCAL_FILE_UPLOAD\"}]")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

